const spreadsheetId = '1GlrDyHe7haN22Z1fU0JPbWfbh0bgEswAqBZNwE3-apc';
const apiBaseUrl = 'http://host.docker.internal:8000';
const httpRequest = this.helpers.httpRequest.bind(this.helpers);

function csvUrl(sheet) {
  return `https://docs.google.com/spreadsheets/d/${spreadsheetId}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent(sheet)}`;
}

function parseCsv(text) {
  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const next = text[i + 1];
    if (quoted) {
      if (ch === '"' && next === '"') {
        cell += '"';
        i++;
      } else if (ch === '"') {
        quoted = false;
      } else {
        cell += ch;
      }
    } else if (ch === '"') {
      quoted = true;
    } else if (ch === ',') {
      row.push(cell);
      cell = '';
    } else if (ch === '\n') {
      row.push(cell.replace(/\r$/, ''));
      rows.push(row);
      row = [];
      cell = '';
    } else {
      cell += ch;
    }
  }
  if (cell || row.length) {
    row.push(cell);
    rows.push(row);
  }
  const headers = (rows.shift() || []).map((value) => String(value).trim());
  return rows.filter((values) => values.some((value) => String(value).trim())).map((values) => {
    const item = {};
    headers.forEach((header, index) => {
      item[header] = values[index] ?? '';
    });
    return item;
  });
}

async function getSheet(sheet) {
  const text = await httpRequest({
    method: 'GET',
    url: csvUrl(sheet),
    json: false,
  });
  return parseCsv(text);
}

async function postJson(path, payload) {
  return await httpRequest({
    method: 'POST',
    url: `${apiBaseUrl}${path}`,
    headers: { 'Content-Type': 'application/json' },
    body: payload,
    json: true,
  });
}

const adsDaily = await getSheet('ads_daily');
const reviews = await getSheet('reviews');
const competitors = await getSheet('competitors');
const ourProducts = await getSheet('our_products');
const keywordPlan = await getSheet('keyword_plan');

const ads = await postJson('/ads/report', { rows: adsDaily, target_drr: 0.18 });
const reviewDrafts = await postJson('/reviews/drafts', { rows: reviews });
const competitor = await postJson('/competitors/opportunities', {
  competitors,
  our_products: ourProducts,
  keyword_plan: keywordPlan,
});
const digest = await postJson('/integrations/telegram/digest', {
  ads_rows: ads.rows,
  review_rows: reviewDrafts.replies,
  ticket_rows: reviewDrafts.tickets,
  opportunity_rows: competitor.opportunities,
  task_rows: competitor.tasks,
});
const notion = await postJson('/integrations/notion/tasks', { tasks: competitor.tasks });

return [{
  json: {
    telegram_digest: digest.text,
    ads_rows: ads.rows.length,
    review_replies: reviewDrafts.replies.length,
    support_tickets: reviewDrafts.tickets.length,
    competitor_opportunities: competitor.opportunities.length,
    notion_tasks: notion.tasks,
  }
}];

const notionToken = 'NOTION_TOKEN';
const databaseId = 'NOTION_DATABASE_ID';
const httpRequest = this.helpers.httpRequest.bind(this.helpers);

function richText(value) {
  return [{ type: 'text', text: { content: String(value || '') } }];
}

function paragraph(text) {
  return {
    object: 'block',
    type: 'paragraph',
    paragraph: { rich_text: richText(text) },
  };
}

function selectProperty(value) {
  const name = String(value || '').trim();
  return name ? { select: { name } } : { select: null };
}

function taskId(task) {
  return String(task.properties?.['Task ID']?.rich_text || task.title || '').trim();
}

function notionProperties(task) {
  const props = task.properties || {};
  return {
    Name: { title: richText(task.title || 'Задача по маркетплейсу') },
    'Task ID': { rich_text: richText(taskId(task)) },
    Priority: selectProperty(props.Priority?.select),
    Owner: selectProperty(props.Owner?.select),
    'Task Type': selectProperty(props['Task Type']?.select),
    Impact: selectProperty(props.Impact?.select),
    SKU: { rich_text: richText(props.SKU?.rich_text) },
    Keyword: { rich_text: richText(props.Keyword?.rich_text) },
    'Due In Days': { number: props['Due In Days']?.number ?? null },
  };
}

function notionPage(task) {
  return {
    parent: { database_id: databaseId },
    properties: notionProperties(task),
    children: (task.content || []).filter(Boolean).map(paragraph),
  };
}

async function findExistingPage(id) {
  if (!id) {
    return null;
  }
  const result = await httpRequest({
    method: 'POST',
    url: `https://api.notion.com/v1/databases/${databaseId}/query`,
    headers: {
      Authorization: `Bearer ${notionToken}`,
      'Notion-Version': '2022-06-28',
      'Content-Type': 'application/json',
    },
    body: {
      page_size: 1,
      filter: {
        property: 'Task ID',
        rich_text: { equals: id },
      },
    },
    json: true,
  });
  return (result.results || [])[0] || null;
}

const created = [];
const updated = [];
for (const task of $json.notion_tasks || []) {
  const id = taskId(task);
  const existing = await findExistingPage(id);
  if (existing) {
    const page = await httpRequest({
      method: 'PATCH',
      url: `https://api.notion.com/v1/pages/${existing.id}`,
      headers: {
        Authorization: `Bearer ${notionToken}`,
        'Notion-Version': '2022-06-28',
        'Content-Type': 'application/json',
      },
      body: { properties: notionProperties(task) },
      json: true,
    });
    updated.push({ id: page.id, url: page.url, title: task.title });
  } else {
    const page = await httpRequest({
      method: 'POST',
      url: 'https://api.notion.com/v1/pages',
      headers: {
        Authorization: `Bearer ${notionToken}`,
        'Notion-Version': '2022-06-28',
        'Content-Type': 'application/json',
      },
      body: notionPage(task),
      json: true,
    });
    created.push({ id: page.id, url: page.url, title: task.title });
  }
}

return [{ json: { created_notion_tasks: created.length, updated_notion_tasks: updated.length, pages: [...created, ...updated] } }];
